import{_ as e,o,c as i,a3 as r}from"./chunks/framework.BFeCKmyl.js";const m=JSON.parse('{"title":"Qualificação da parte na intimação","description":"","frontmatter":{"title":"Qualificação da parte na intimação","id":"eproc-qualificacao-parte-intimacao","plataforma":"eproc","grupo":"Árvore e minuta","plano":"free","desde":"1.15.0","padrao":"ligado","head":[["link",{"rel":"canonical","href":"https://eploc.com.br/manual/funcionalidades/eproc-qualificacao-parte-intimacao"}],["meta",{"property":"og:url","content":"https://eploc.com.br/manual/funcionalidades/eproc-qualificacao-parte-intimacao"}],["meta",{"property":"og:title","content":"Qualificação da parte na intimação | Manual do eploc"}],["meta",{"property":"og:description","content":"Manual oficial do eploc, extensão para Chrome e Edge que acelera o trabalho no eproc, SEI e RUPE."}]]},"headers":[],"relativePath":"funcionalidades/eproc-qualificacao-parte-intimacao.md","filePath":"funcionalidades/eproc-qualificacao-parte-intimacao.md"}'),t={name:"funcionalidades/eproc-qualificacao-parte-intimacao.md"};function n(s,a,c,l,p,d){return o(),i("div",null,a[0]||(a[0]=[r('<h1 id="qualificacao-da-parte-na-intimacao" tabindex="-1">Qualificação da parte na intimação <a class="header-anchor" href="#qualificacao-da-parte-na-intimacao" aria-label="Permalink to &quot;Qualificação da parte na intimação&quot;">​</a></h1><h2 id="o-que-faz" tabindex="-1">O que faz <a class="header-anchor" href="#o-que-faz" aria-label="Permalink to &quot;O que faz&quot;">​</a></h2><p>Na capa do processo, algumas partes trazem uma qualificação entre parênteses na tabela de partes, como &quot;(Inventariante)&quot; ou &quot;(Espólio)&quot;. Na tela de intimação, cada parte aparece só com o nome e o polo, e não dá para saber, por exemplo, qual dos requerentes é a inventariante. Este recurso mostra essa qualificação num selo azul ao lado do nome da parte na escolha das partes a intimar.</p><h2 id="onde-aparece" tabindex="-1">Onde aparece <a class="header-anchor" href="#onde-aparece" aria-label="Permalink to &quot;Onde aparece&quot;">​</a></h2><p><strong>eproc</strong>, na escolha das partes a intimar:</p><ul><li>na tela de intimação do processo;</li><li>no &quot;Intimar/Citar&quot; do cadastro e da edição de minuta.</li></ul><h2 id="passo-a-passo" tabindex="-1">Passo a passo <a class="header-anchor" href="#passo-a-passo" aria-label="Permalink to &quot;Passo a passo&quot;">​</a></h2><ol><li>Abra o processo. A tabela &quot;Partes e Representantes&quot; mostra a qualificação de alguma parte, como &quot;(Inventariante)&quot;.</li><li>A partir da página do processo, abra a intimação.</li><li>Ao lado do nome dessa parte aparece um selo com a qualificação.</li></ol><h2 id="configuracoes-e-opcoes" tabindex="-1">Configurações e opções <a class="header-anchor" href="#configuracoes-e-opcoes" aria-label="Permalink to &quot;Configurações e opções&quot;">​</a></h2><p>Não há opções além de ligar e desligar.</p><h2 id="observacoes" tabindex="-1">Observações <a class="header-anchor" href="#observacoes" aria-label="Permalink to &quot;Observações&quot;">​</a></h2><ul><li>A qualificação vem da página do processo. Se a intimação for aberta por outro caminho, sem passar pela página do processo, o selo não aparece.</li><li>Se o polo tiver o link &quot;e outros&quot;, as partes só entram depois de carregadas na página do processo.</li><li>A parte é reconhecida pelo nome. O selo só informa: as partes marcadas e os prazos não mudam.</li></ul>',12)]))}const f=e(t,[["render",n]]);export{m as __pageData,f as default};
